from taf.internal.scf.managed_object import ManagedObject as TafManagedObject
from taf.internal.scf.list import List as TafList
from taf.internal.scf.list import Item as TafItem
from taf.internal.scf.list import P as TafP

from taf.ul.auto_commissioning.utils import assure_is_list, remove_mrbts_and_nrbts_part, is_full_distname,\
    change_mrbts_id_and_nrbts_id, change_mrbtsid


class ManagedObject:

    def __hash__(self):
        return hash(str(self.dist_name_without_mr_nr_bts))

    def __init__(self, klass, dist_name, version, operation):
        self.klass = klass
        self.dist_name = dist_name
        self.version = version
        self.operation = operation

        self.params = []
        self.lists = []

    @property
    def dist_name_without_mr_nr_bts(self):
        """Without MRBTS-{int} and NRBTS-{int}"""
        return remove_mrbts_and_nrbts_part(self.dist_name)

    @property
    def link_params(self):
        """Params that have distnames of objects as their values"""
        return [param for param in self.params if param.is_linking_to_mo]

    @classmethod
    def create_from_xml_dict(cls, managed_obj_dict):
        mo = ManagedObject(
            klass=managed_obj_dict["@class"],
            dist_name=managed_obj_dict["@distName"],
            version=managed_obj_dict["@version"],
            operation=managed_obj_dict["@operation"])
        mo.params = P.create_multiple_from_xml_managed_object_dict(managed_obj_dict)
        mo.lists = List.create_multiple_from_xml_managed_object_dict(managed_obj_dict)
        return mo

    @classmethod
    def create_from_dict(cls, managed_obj_dict):
        mo = ManagedObject(
            klass=managed_obj_dict["klass"],
            dist_name=managed_obj_dict["dist_name"],
            version=managed_obj_dict["version"],
            operation=managed_obj_dict["operation"])
        mo.params = [P.create_from_dict(p) for p in managed_obj_dict["params"]]
        mo.lists = [List.create_from_dict(lst) for lst in managed_obj_dict["lists"]]
        return mo

    def translate_to_dict(self):
        return {
            "klass": self.klass,
            "dist_name": self.dist_name,
            "version": self.version,
            "operation": self.operation,
            "params": [p.translate_to_dict() for p in self.params],
            "lists": [lst.translate_to_dict() for lst in self.lists]
        }

    def translate_to_taf_object(self):
        taf_managed = TafManagedObject().create(
            klass=self.klass,
            dist_name=self.dist_name,
            version=self.version,
            operation=self.operation)
        [taf_managed.append(l.translate_to_taf_object()) for l in self.lists]
        [taf_managed.append(p.translate_to_taf_object()) for p in self.params]

        return taf_managed

    def change_mrbts_id_and_nrbts_id_in_link(self, mrbts_id, nrbts_id):
        """Params can be linking to MO's, this method enables changing all MRBTS IDs in those links"""
        [param.change_mrbts_id_and_nrbts_id_in_link(mrbts_id, nrbts_id) for param in self.link_params]
        [lst.change_mrbts_id_and_nrbts_id_in_link(mrbts_id, nrbts_id) for lst in self.lists]

    def change_mrbts_id_in_link(self, mrbts_id):
        """Params can be linking to MO's, this method enables changing all MRBTS IDs in those links"""
        [param.change_mrbts_id_in_link(mrbts_id) for param in self.link_params]
        [lst.change_mrbts_id_in_link(mrbts_id) for lst in self.lists]

    def __eq__(self, other):
        if not isinstance(other, ManagedObject):
            return NotImplemented

        return bool(sorted(self.params) == sorted(other.params)
                    and sorted(self.lists) == sorted(other.lists)
                    and self.dist_name_without_mr_nr_bts == other.dist_name_without_mr_nr_bts
                    and self.klass == other.klass
                    and self.version == other.version
                    and self.operation == other.operation)

    def __ne__(self, other):
        if not isinstance(other, ManagedObject):
            return NotImplemented

        return bool(sorted(self.params) != sorted(other.params)
                    or sorted(self.lists) != sorted(other.lists)
                    or self.dist_name_without_mr_nr_bts != other.dist_name_without_mr_nr_bts
                    or self.klass != other.klass
                    or self.version != other.version
                    or self.operation != other.operation)

    def __lt__(self, other):
        """for sorting"""
        return True if self.dist_name < other.dist_name else False


class List:

    def __init__(self, name):
        self.name = name

        self.params = []
        self.items = []

    @property
    def link_params(self):
        """Params that have distnames of objects as their values"""
        return [param for param in self.params if param.is_linking_to_mo]

    @classmethod
    def create_multiple_from_xml_managed_object_dict(cls, managed_obj_dict):
        list_dicts = assure_is_list(managed_obj_dict.get("list"))
        return [List.create_from_xml_dict(l_dict) for l_dict in list_dicts]

    @classmethod
    def create_from_xml_dict(cls, list_dict):
        lst = List(str(list_dict["@name"]))
        lst.params = P.create_multiple_from_xml_list_dict(list_dict)
        lst.items = Item.create_multiple_from_xml_list_dict(list_dict)
        return lst

    @classmethod
    def create_from_dict(cls, list_dict):
        lst = List(name=list_dict["name"])
        lst.params = [P.create_from_dict(p) for p in list_dict["params"]]
        try:
            lst.items = [Item.create_from_dict(i) for i in list_dict["items"]]
        except KeyError:
            # TODO this is a backwards compatibility fix for deltas where lists with only one item were possible
            lst.items = [Item.create_from_dict(list_dict["item"]) if list_dict["item"] else list_dict["item"]]
        return lst

    def translate_to_taf_object(self):
        taf_list = TafList().create(name=self.name)
        [taf_list.append(p.translate_to_taf_object()) for p in self.params]
        try:
            [taf_list.append(item.translate_to_taf_object()) for item in self.items]
        except AttributeError:
            # TODO case self.items == [None] due to legacy where deltas has lists with only one item
            pass
        return taf_list

    def translate_to_dict(self):
        return {
            "name": self.name,
            "params": [p.translate_to_dict() for p in self.params],
            # "item": self.item.translate_to_dict() if self.item else self.item
            "items": [i.translate_to_dict() for i in self.items]
        }

    def change_mrbts_id_and_nrbts_id_in_link(self, mrbts_id, nrbts_id):
        """Params can be linking to MO's, this method enables changing all MRBTS IDs in those links"""
        [param.change_mrbts_id_and_nrbts_id_in_link(mrbts_id, nrbts_id) for param in self.link_params]
        try:
            [item.change_mrbts_id_and_nrbts_id_in_link(mrbts_id, nrbts_id) for item in self.items]
        except AttributeError:
            # TODO case self.items == [None] due to legacy where deltas has lists with only one item
            pass

    def change_mrbts_id_in_link(self, mrbts_id):
        """Params can be linking to MO's, this method enables changing all MRBTS IDs in those links"""
        [param.change_mrbts_id_in_link(mrbts_id) for param in self.link_params]
        [item.change_mrbts_id_in_link(mrbts_id) for item in self.items]

    def __eq__(self, other):
        if not isinstance(other, List):
            return NotImplemented

        return bool(self.name == other.name and self.params == other.params and self.items == other.items)

    def __ne__(self, other):
        if not isinstance(other, List):
            return NotImplemented

        return bool(self.name != other.name or self.params != other.params or self.items != other.items)

    def __lt__(self, other):
        """for sorting"""
        return bool(self.name < other.name)


class Item:

    def __init__(self):
        self.params = []

    @property
    def link_params(self):
        """Params that have distnames of objects as their values"""
        return [param for param in self.params if param.is_linking_to_mo]

    @classmethod
    def create_multiple_from_xml_list_dict(cls, list_dict):
        item_dicts = assure_is_list(list_dict.get("item"))

        items = []
        for i in item_dicts:
            item = Item()
            item.params = P.create_multiple_from_xml_item_dict(i)
            items.append(item)
        return items

    @classmethod
    def create_from_dict(cls, item_dict):
        item = Item()
        item.params = [P.create_from_dict(p) for p in item_dict["params"]]
        return item

    def translate_to_taf_object(self):
        taf_item = TafItem().create()
        [taf_item.append(p.translate_to_taf_object()) for p in self.params]
        return taf_item

    def translate_to_dict(self):
        return {
            "params": [p.translate_to_dict() for p in self.params]
        }

    def change_mrbts_id_and_nrbts_id_in_link(self, mrbts_id, nrbts_id):
        """Params can be linking to MO's, this method enables changing all MRBTS IDs in those links"""
        [param.change_mrbts_id_and_nrbts_id_in_link(mrbts_id, nrbts_id) for param in self.link_params]

    def change_mrbts_id_in_link(self, mrbts_id):
        """Params can be linking to MO's, this method enables changing all MRBTS IDs in those links"""
        [param.change_mrbts_id_in_link(mrbts_id) for param in self.link_params]

    def __eq__(self, other):
        if not isinstance(other, Item):
            return NotImplemented

        return bool(sorted(self.params) == sorted(other.params))

    def __ne__(self, other):
        if not isinstance(other, Item):
            return NotImplemented

        return bool(sorted(self.params) != sorted(other.params))


class P:

    def __init__(self, value="", name=None):
        self.name = name
        self.value = value

    @property
    def is_linking_to_mo(self):
        """These are params that have value of full distname, starting with MRBTS- and having / in it"""
        return bool(is_full_distname(self.value))

    @classmethod
    def create_multiple_from_xml_managed_object_dict(cls, managed_object_dict):
        all_params_dicts = assure_is_list(managed_object_dict.get("p"))
        if all_params_dicts:
            return [cls._create_from_xml_param_dict(p_dict) for p_dict in all_params_dicts]
        else:
            return []

    @classmethod
    def create_multiple_from_xml_list_dict(cls, list_dict):
        all_param_values = assure_is_list(list_dict.get("p"))
        if all_param_values:
            return [P(value=val) for val in all_param_values]
        else:
            return []

    @classmethod
    def create_multiple_from_xml_item_dict(cls, item_dict):
        ps = []
        for p_dict in assure_is_list(item_dict.get("p")):
            ps.append(P._create_from_xml_param_dict(p_dict))
        return ps

    @classmethod
    def _create_from_xml_param_dict(cls, param_dict):
        return P(name=param_dict.get("@name"), value=param_dict.get("#text", ""))

    @classmethod
    def create_from_dict(cls, param_dict):
        return P(name=param_dict["name"], value=param_dict.get("value", ""))

    def translate_to_taf_object(self):
        return TafP().create(value=self.value, name=self.name)

    def translate_to_dict(self):
        return {
            "name": self.name,
            "value": self.value
        }

    def change_mrbts_id_and_nrbts_id_in_link(self, mrbts_id, nrbts_id):
        """If Param is a link - it will change ID in its link"""
        if self.is_linking_to_mo:
            self.value = change_mrbts_id_and_nrbts_id(self.value, mrbts_id, nrbts_id)

    def change_mrbts_id_in_link(self, mrbts_id):
        """If Param is a link - it will change ID in its link"""
        if self.is_linking_to_mo:
            self.value = change_mrbtsid(self.value, mrbts_id)

    def __eq__(self, other):
        if not isinstance(other, P):
            return NotImplemented

        return bool(self.name == other.name and self.value == other.value)

    def __ne__(self, other):
        if not isinstance(other, P):
            return NotImplemented

        return bool(self.name != other.name or self.value != other.value)

    def __lt__(self, other):
        """for sorting"""
        return bool(self.value < other.value)
